from typing import List, Tuple

def text_editor(operations: List[Tuple[str, str]]) -> str:
    """
    Simulates a simple text editor supporting "add" and "undo" operations.

    Parameters:
    operations (List[Tuple[str, str]]): List of operations (either "add" or "undo").

    Returns:
    str: Final state of the text after all operations.
    """
    stack = []

    for op, value in operations:
        if op == "add":
            stack.append(value)
        elif op == "undo" and stack:
            stack.pop()

    return ''.join(stack)

