def maxDistToClosest(seats):
    """
    Returns the maximum distance to the closest person.
    """
    max_dist = 0
    last_occupied = -1

    for i, seat in enumerate(seats):
        if seat == 1:
            if last_occupied == -1:
                max_dist = i
            else:
                max_dist = max(max_dist, (i - last_occupied) // 2)
            last_occupied = i

    max_dist = max(max_dist, len(seats) - 1 - last_occupied)

    return max_dist

