def is_possible_subset(n, m, k, arr):
    """
    Determines if there exists a subset of the given list 'arr' such that
    the difference between the maximum and minimum value in this subset is exactly 'k'.
    """
    arr_set = set(arr)

    for num in arr:
        if (num + k) in arr_set:
            return "YES"

    return "NO"

def count_paths(N, M, grid):
    """
    Returns the number of valid paths from the top-left intersection
    to the bottom-right intersection in the given grid.
    """
    if grid[0][0] == 1 or grid[N-1][M-1] == 1:
        return 0

    dp = [[0]*M for _ in range(N)]

    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[N-1][M-1]

