def compress_string(s):
    """
    Compress the string using the specified algorithm.

    Parameters:
    s (str): The input string containing only lowercase Latin letters.

    Returns:
    str: The compressed version of the input string.
    """
    if not s:
        return ""

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1])
            if count > 1:
                compressed.append(str(count))
            count = 1

    # Add the last group
    compressed.append(s[-1])
    if count > 1:
        compressed.append(str(count))

    return ''.join(compressed)

