from typing import List

def max_sum_subarray(nums: List[int], k: int) -> List[int]:
    if not nums or k <= 0 or k > len(nums):
        return []

    max_sum = float('-inf')
    current_sum = 0
    max_subarray_start_index = 0

    for i in range(k):
        current_sum += nums[i]

    max_sum = current_sum

    for i in range(k, len(nums)):
        current_sum += nums[i] - nums[i - k]
        if current_sum > max_sum:
            max_sum = current_sum
            max_subarray_start_index = i - k + 1

    return nums[max_subarray_start_index:max_subarray_start_index + k]

