def four_sum_exists(nums, target):
    """
    Returns True if there exist four distinct indices `a, b, c, d` such that `nums[a] + nums[b] + nums[c] + nums[d]` is equal to `target`, otherwise returns False.
    """
    if len(nums) < 4:
        return False

    nums.sort()
    n = len(nums)

    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            left = j + 1
            right = n - 1
            while left < right:
                s = nums[i] + nums[j] + nums[left] + nums[right]
                if s == target:
                    return True
                elif s < target:
                    left += 1
                else:
                    right -= 1
    return False

