def process_queue_operations(n, operations):
    """
    Processes a sequence of queue operations and returns the final state of the queue.

    Parameters:
    n : int
        Number of operations
    operations : list of str
        List of operations, either 'enqueue X' or 'dequeue'

    Returns:
    str
        Final state of the queue as a space separated string,
        or 'Empty Queue' if the queue is empty.
    """
    queue = []

    for operation in operations:
        if operation.startswith('enqueue'):
            _, x = operation.split()
            queue.append(int(x))
        elif operation == 'dequeue':
            if queue:
                queue.pop(0)

    if queue:
        return ' '.join(map(str, queue))
    else:
        return 'Empty Queue'

