from typing import Union, List, Dict

def max_depth(nested_structure: Union[List, Dict]) -> int:
    """
    Determine the maximum depth of a nested data structure composed of lists and dictionaries.
    """
    if isinstance(nested_structure, list):
        # If it's a list, check the depth of each element
        if not nested_structure:
            # An empty list has a depth of 1
            return 1
        return 1 + max(max_depth(element) for element in nested_structure)
    elif isinstance(nested_structure, dict):
        # If it's a dict, check the depth of each value
        if not nested_structure:
            # An empty dictionary has a depth of 1
            return 1
        return 1 + max(max_depth(value) for value in nested_structure.values())
    else:
        # If it's neither a list nor a dict, it has no further depth
        return 0

