def hotel_reservation_system(n, q, room_ids, requests):
    bookings = {room_id: [] for room_id in room_ids}

    result = []
    for request in requests:
        room_id, start_date, end_date = request
        if room_id not in bookings:
            result.append("NO")
            continue

        room_bookings = bookings[room_id]

        # Check for overlapping bookings
        available = True
        for booking in room_bookings:
            if not (end_date < booking[0] or start_date > booking[1]):
                available = False
                break

        if available:
            bookings[room_id].append((start_date, end_date))
            result.append("YES")
        else:
            result.append("NO")

    return result

