from itertools import combinations

def count_combinations(nums, target):
    """
    Returns the number of unique combinations that can be formed by choosing elements from the array
    where the sum equals the target. Each number in nums can be used once in each combination.
    """
    count = 0
    for r in range(1, len(nums) + 1):
        for combo in combinations(nums, r):
            if sum(combo) == target:
                count += 1
    return count

