def longest_streak(temp):
    """
    Returns the length of the longest streak of non-decreasing temperatures.
    """
    if not temp:
        return 0

    max_streak = 1
    current_streak = 1

    for i in range(1, len(temp)):
        if temp[i] >= temp[i - 1]:
            current_streak += 1
            max_streak = max(max_streak, current_streak)
        else:
            current_streak = 1 # reset the streak

    return max_streak

