    Returns the length of the longest substring with at most two distinct characters.
    """
    if not s:
        return 0

    left = 0
    right = 0
    max_length = 0
    char_map = {}

    while right < len(s):
        if len(char_map) < 2 or s[right] in char_map:
            char_map[s[right]] = char_map.get(s[right], 0) + 1
            right += 1
        else:
            while len(char_map) >= 2:
                char_map[s[left]] -= 1
                if char_map[s[left]] == 0:
                    del char_map[s[left]]
                left += 1

        max_length = max(max_length, right - left)

    return max_length

