def can_rearrange_grades(test_cases):
    results = []
    for case in test_cases:
        n, grades = case
        grades.sort()
        possible = True
        for i in range(1, n):
            if grades[i] - grades[i-1] > 1:
                possible = False
                break
        results.append("YES" if possible else "NO")
    return results

